-- Ensure only one pending clarification per conversation
CREATE UNIQUE INDEX IF NOT EXISTS "MessagingClarification_conversationId_pending_key"
  ON "MessagingClarification"("conversationId")
  WHERE "status" = 'PENDING';

-- Optimize lookups by conversation + status
CREATE INDEX IF NOT EXISTS "MessagingClarification_conversationId_status_idx"
  ON "MessagingClarification"("conversationId", "status");
